SELECT CASE WHEN YEAR(ss.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(ss.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, QUARTER(ss.sale_date) AS sale_quarter, COUNT(DISTINCT i.quantity) AS unique_products, COUNT(*) AS cnt FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY CASE WHEN YEAR(ss.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(ss.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END, QUARTER(ss.sale_date) ORDER BY unique_products, cnt, sale_cohort, sale_quarter LIMIT 5
